mapper.select:
/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectUneartMngStatsList[발굴관리통계] */ /* Lee SangHoon */
WITH TMP AS( SELECT A.CASE_TRPR_TYPE_SE_CD AS CD1 , CASE WHEN A.CASE_TRPR_TYPE_SE_CD = '02' AND A.RCPT_RQST_COURS_SE_CD IN ('02020101', '02020102', '02020103', '02020104', '02020105', '02020106', '02020107', '02020108', '02020109', '02020110', '02020112') THEN A.RCPT_RQST_COURS_SE_CD ELSE A.CASE_TRPR_TYPE_SE_CD END AS CD2 , A.SXDC_SE_CD AS SX -- 성별구분코드 , A.TRPR_INFO_NO AS TRPR_INFO_NO -- 대상자정보번호 , A.CASE_MNG_SE_CD AS CASE_MNG_SE_CD -- 사례관리구분코드(04:사례대상자선정) , NVL(A.INDV_IDNTFC_NO,A.TRPR_INFO_NO) AS INDV_IDNTFC_NO -- 개인식별번호(없을시 대상자정보번호) , CASE A.CASE_TRPR_TYPE_SE_CD WHEN '10' THEN B.ACT_CNT WHEN '11' THEN C.ACT_CNT WHEN '15' THEN D.ACT_CNT WHEN '12' THEN E.ACT_CNT ELSE 0 END AS ACT_CNT FROM SEA200 A /*대상자정보*/ LEFT JOIN ( SELECT TRPR_INFO_NO , COUNT(ERYY_DSCSN_NO) AS ACT_CNT FROM SEA110 WHERE DEL_YN = 'N' GROUP BY TRPR_INFO_NO ) B ON A.TRPR_INFO_NO = B.TRPR_INFO_NO AND A.CASE_TRPR_TYPE_SE_CD = '10' -- 발굴상담대상자 LEFT JOIN ( SELECT TRPR_INFO_NO , COUNT(ERYY_GR_DSCSN_NO) AS ACT_CNT FROM SEA130 WHERE DEL_YN = 'N' GROUP BY TRPR_INFO_NO ) C /*집단상담후조치*/ ON A.TRPR_INFO_NO = C.TRPR_INFO_NO AND A.CASE_TRPR_TYPE_SE_CD = '11' -- 아웃리치대상자 LEFT JOIN ( SELECT TRPR_INFO_NO , COUNT(CO13_MNG_NO) AS ACT_CNT FROM ACA140 GROUP BY TRPR_INFO_NO ) D /*1388전화상담*/ ON A.TRPR_INFO_NO = D.TRPR_INFO_NO AND A.CASE_TRPR_TYPE_SE_CD = '15' -- 1388전화상담대상자 LEFT JOIN ( SELECT TRPR_INFO_NO , COUNT(EMRG_INTRVN_NO) AS ACT_CNT FROM SEA220 WHERE DEL_YN = 'N' GROUP BY TRPR_INFO_NO ) E /*긴급개입*/ ON A.TRPR_INFO_NO = E.TRPR_INFO_NO AND A.CASE_TRPR_TYPE_SE_CD = '12' -- 긴급구조대상자 LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = A.RCPT_INST_NO AND F3.DEL_YN = 'N'
WHERE 1=1 AND A.DEL_YN = 'N' AND A.CASE_TRPR_TYPE_SE_CD > '0' -- 단위업무구분코드 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.FRST_REG_DT BETWEEN TO_DATE(#{SRT_DT} || '000000', 'YYYYMMDDHH24MISS') AND TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,A.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,A.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,A.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,A.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,A.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND A.TRPR_BRTH_YMD IS NULL
-- 연령 기타
-- 가족형태구분코드 AND A.FAM_SHAPE_SE_CD = #{FAM_SHAPE_SE_CD}
-- 공적부조구분코드 AND A.PBLAST_SE_CD = #{PBLAST_SE_CD}
-- 가족특성구분코드 AND A.FAM_CHAR_SE_CD = #{FAM_CHAR_SE_CD}
-- 의뢰경로대분류구분코드 AND SUBSTR(A.RCPT_RQST_COURS_SE_CD,1,2) = #{RCPT_RQST_COURS_LCLAS_SE_CD}
-- 의뢰경로중분류구분코드 AND SUBSTR(A.RCPT_RQST_COURS_SE_CD,1,4) = #{RCPT_RQST_COURS_MLSFC_SE_CD}
)
SELECT A.T_NM , C.CMMNS_CD_VALUE_NM AS SXDC , NVL(B.CASE_TOT_CNT,0) AS CASE_TOT_CNT , NVL(B.IDNO_CNT,0) AS IDNO_CNT , NVL(B.ACT_CNT,0) AS ACT_CNT , NVL(B.CASE_CNT_1,0) AS CASE_CNT_1 , NVL(B.CASE_CNT_2,0) AS CASE_CNT_2 FROM ( -- 통계 틀 만들기 SELECT A.CMMNS_CD_VALUE AS T_CD1 , A.CMMNS_CD_VALUE AS T_CD2 , A.CMMNS_CD_VALUE_NM AS T_NM , A.SRTNG_SQNCE AS T_SN , B.SXDC_SE_CD AS T_SX FROM SAC100 A CROSS JOIN ( SELECT '0T' AS SXDC_SE_CD FROM DUAL UNION SELECT '1M' FROM DUAL UNION SELECT '2F' FROM DUAL UNION SELECT '3X' FROM DUAL ) B WHERE A.CMMNS_CD_ID = 'CASE_TRPR_TYPE_SE_CD' AND CMMNS_CD_VALUE <> '02' AND USE_YN = 'Y' UNION ALL -- 통계 틀 만들기 2(여성가족부기관연계접수) SELECT A.CMMNS_CD_VALUE AS CD1 , C.CMMNS_CD_VALUE AS CD2 , C.CMMNS_CD_VALUE_NM AS NM , A.SRTNG_SQNCE AS T_SN , B.SXDC_SE_CD AS SXDC_SE_CD FROM SAC100 A CROSS JOIN ( SELECT '0T' AS SXDC_SE_CD FROM DUAL UNION SELECT '1M' FROM DUAL UNION SELECT '2F' FROM DUAL UNION SELECT '3X' FROM DUAL ) B CROSS JOIN ( SELECT CMMNS_CD_VALUE, CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'RCPT_RQST_COURS_SE_CD' AND ADDTNG_MNG_VALUE1 LIKE 'U%' AND USE_YN = 'Y' ) C WHERE A.CMMNS_CD_ID = 'CASE_TRPR_TYPE_SE_CD' AND A.CMMNS_CD_VALUE = '02' AND A.USE_YN = 'Y' UNION ALL -- 통계 틀 만들기 3(합계) SELECT '00' , '00' , '합계' , 0 , SXDC_SE_CD FROM ( SELECT '0T' AS SXDC_SE_CD FROM DUAL UNION SELECT '1M' FROM DUAL UNION SELECT '2F' FROM DUAL UNION SELECT '3X' FROM DUAL ) ) A LEFT JOIN ( -- 기본 통계 결과(남,여,미확인) SELECT CD1 -- 발굴구분 , CD2 -- 여성가족부기관 연계접수에서만 사용 , SX -- 성별 , COUNT(TRPR_INFO_NO) AS CASE_TOT_CNT -- 전체 사례진행수(계) = 전체 발굴인원수 , COUNT(CASE WHEN CASE_MNG_SE_CD = '04' THEN TRPR_INFO_NO END) AS CASE_CNT_1 -- 진행인원수(사례건수) , COUNT(CASE WHEN CASE_MNG_SE_CD != '04' THEN TRPR_INFO_NO END) AS CASE_CNT_2 -- 미진행인원수(미사례건수) , COUNT(DISTINCT INDV_IDNTFC_NO) AS IDNO_CNT -- 발굴현황(식별수) , SUM(ACT_CNT) AS ACT_CNT -- 발굴활동 건수 FROM TMP GROUP BY CD1, CD2, SX UNION ALL -- 기본 통계 결과(전체) SELECT CD1 -- 발굴구분 , CD2 -- 여성가족부기관 연계접수에서만 사용 , 'T' AS SX -- 성별 , COUNT(TRPR_INFO_NO) AS CASE_TOT_CNT -- 전체 사례진행수(계) = 전체 발굴인원수 , COUNT(CASE WHEN CASE_MNG_SE_CD = '04' THEN TRPR_INFO_NO END) AS CASE_CNT_1 -- 진행인원수(사례건수) , COUNT(CASE WHEN CASE_MNG_SE_CD != '04' THEN TRPR_INFO_NO END) AS CASE_CNT_2 -- 미진행인원수(미사례건수) , COUNT(DISTINCT INDV_IDNTFC_NO) AS IDNO_CNT -- 발굴현황(식별수) , SUM(ACT_CNT) AS ACT_CNT -- 발굴활동 건수 FROM TMP GROUP BY CD1, CD2 UNION ALL -- 기본 통계 합계(남,여,미확인) SELECT '00' -- 발굴구분 , '00' -- 여성가족부기관 연계접수에서만 사용 , SX -- 성별 , COUNT(TRPR_INFO_NO) AS CASE_TOT_CNT -- 전체 사례진행수(계) = 전체 발굴인원수 , COUNT(CASE WHEN CASE_MNG_SE_CD = '04' THEN TRPR_INFO_NO END) AS CASE_CNT_1 -- 진행인원수(사례건수) , COUNT(CASE WHEN CASE_MNG_SE_CD != '04' THEN TRPR_INFO_NO END) AS CASE_CNT_2 -- 미진행인원수(미사례건수) , COUNT(DISTINCT INDV_IDNTFC_NO) AS IDNO_CNT -- 발굴현황(식별수) , SUM(ACT_CNT) AS ACT_CNT -- 발굴활동 건수 FROM TMP GROUP BY SX UNION ALL -- 기본 통계 합계(전체) SELECT '00' -- 발굴구분 , '00' -- 여성가족부기관 연계접수에서만 사용 , 'T' AS SX -- 성별 , COUNT(TRPR_INFO_NO) AS CASE_TOT_CNT -- 전체 사례진행수(계) = 전체 발굴인원수 , COUNT(CASE WHEN CASE_MNG_SE_CD = '04' THEN TRPR_INFO_NO END) AS CASE_CNT_1 -- 진행인원수(사례건수) , COUNT(CASE WHEN CASE_MNG_SE_CD != '04' THEN TRPR_INFO_NO END) AS CASE_CNT_2 -- 미진행인원수(미사례건수) , COUNT(DISTINCT INDV_IDNTFC_NO) AS IDNO_CNT -- 발굴현황(식별수) , SUM(ACT_CNT) AS ACT_CNT -- 발굴활동 건수 FROM TMP ) B ON A.T_CD1 = B.CD1 AND A.T_CD2 = B.CD2 AND SUBSTR(A.T_SX,2,2) = B.SX JOIN ( SELECT CMMNS_CD_VALUE_NM, CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' UNION ALL SELECT '전체' AS CMMNS_CD_VALUE_NM, 'T' AS CMMNS_CD_VALUE FROM DUAL) C ON C.CMMNS_CD_VALUE = SUBSTR(A.T_SX,2,2)
ORDER BY A.T_SN, A.T_CD2, A.T_SX

/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectCaseMngBassStatsList[사례관리기본통계] */ /* Lee HyeSun */ WITH X AS ( SELECT DISTINCT A.CASE_PRGRS_STTS_SE_CD --사례진행상태구분코드 , B.TRPR_INFO_NO --대상자정보번호 , A.AFTFCT_MNG_YN --사후관리여부 , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , A.CASE_BGNG_YMD --사례시작일자 , A.CASE_TRMN_YMD --사례종결일자 , B.SXDC_SE_CD --성별구분 , C.AFTFCT_TRMN_YMD --사후종결일자 , TO_DATE(#{SRT_DT} || '000000', 'YYYYMMDDHH24MISS') AS SRT_DT --검색조건시작 , TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS') AS END_DT --검색조건종료 FROM SEB100 A JOIN SEA200 B ON A.TRPR_INFO_NO = B.TRPR_INFO_NO LEFT JOIN SEC320 C ON A.CASE_MNG_NO = C.CASE_MNG_NO AND A.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO LEFT JOIN SEB130 D ON A.CASE_MNG_NO = D.CASE_MNG_NO AND A.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO LEFT JOIN SEB150 F0 /*사례담당자*/ ON F0.PCHPRS_YN = 'Y' AND F0.CASE_MNG_NO = A.CASE_MNG_NO AND F0.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F0.PIC_INST_NO LEFT JOIN AKA500 F4 ON F4.INST_NO = F3.INST_NO
WHERE 1=1 -- 단위업무구분코드 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.FRST_REG_DT BETWEEN TO_DATE(#{SRT_DT} || '000000', 'YYYYMMDDHH24MISS') AND TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
AND (A.CASE_MNG_NO, A.CASE_MNG_ODRNO) IN (SELECT YY.CASE_MNG_NO,YY.CASE_MNG_ODRNO FROM SEB150 YY WHERE 1=1 AND YY.PIC_INST_NO = #{INST_NOS[0]}
)
AND EXISTS (SELECT 1 FROM SEB150 YY WHERE A.CASE_MNG_NO = YY.CASE_MNG_NO AND A.CASE_MNG_ODRNO = YY.CASE_MNG_ODRNO AND YY.PIC_INST_NO IN
#{item}
)
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND B.TRPR_BRTH_YMD IS NULL
-- 연령 기타
-- 가족형태구분코드 AND B.FAM_SHAPE_SE_CD = #{FAM_SHAPE_SE_CD}
-- 공적부조구분코드 AND B.PBLAST_SE_CD = #{PBLAST_SE_CD}
-- 가족특성구분코드 AND B.FAM_CHAR_SE_CD = #{FAM_CHAR_SE_CD}
-- 의뢰경로대분류구분코드 AND SUBSTR(B.RCPT_RQST_COURS_SE_CD,1,2) = #{RCPT_RQST_COURS_LCLAS_SE_CD}
-- 의뢰경로중분류구분코드 AND SUBSTR(B.RCPT_RQST_COURS_SE_CD,1,4) = #{RCPT_RQST_COURS_MLSFC_SE_CD}
-- 문제상태대분류코드 AND D.PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD}
-- 시설유형구분코드 AND F4.FCLTY_TYPE_SE_CD = #{FCLTY_TYPE_SE_CD}
) SELECT A.SCN_CD , A.SCN_NM , A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM , NVL(B.CASE_SPRT, 0) AS CASE_SPRT -- 사례지원중 , NVL(B.AFTFCT_MNG, 0) AS AFTFCT_MNG --사후관리중 , NVL(B.CASE_TRMN, 0) AS CASE_TRMN --사례종결 FROM ( --통계 틀 SELECT '00' AS SCN_CD , '합계' AS SCN_NM , A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM FROM DUAL CROSS JOIN ( SELECT 'T' AS CMMNS_CD_VALUE , '전체' AS CMMNS_CD_VALUE_NM FROM DUAL UNION ALL SELECT CMMNS_CD_VALUE , CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' ) A UNION ALL SELECT '01' AS SCN_CD , '기존' AS SCN_NM , A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM FROM DUAL CROSS JOIN ( SELECT 'T' AS CMMNS_CD_VALUE , '전체' AS CMMNS_CD_VALUE_NM FROM DUAL UNION ALL SELECT CMMNS_CD_VALUE , CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' ) A UNION ALL SELECT '02' AS SCN_CD , '신규' AS SCN_NM , A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM FROM DUAL CROSS JOIN ( SELECT 'T' AS CMMNS_CD_VALUE , '전체' AS CMMNS_CD_VALUE_NM FROM DUAL UNION ALL SELECT CMMNS_CD_VALUE , CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' ) A ) A LEFT JOIN ( ( /*합계*/ SELECT COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('06') AND AFTFCT_MNG_YN = 'Y' THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('04', '08', '10') THEN 1 END) AS CASE_TRMN , 'T' AS SXDC_SE_CD , '00' AS SCN_CD FROM X A UNION ALL SELECT COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('06') AND AFTFCT_MNG_YN = 'Y' THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('04', '08', '10') THEN 1 END) AS CASE_TRMN , SXDC_SE_CD , '00' AS SCN_CD FROM X A GROUP BY SXDC_SE_CD ) UNION ALL ( /*기존*/ SELECT COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('06') AND AFTFCT_MNG_YN = 'Y' THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('04') THEN CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN 1 END WHEN CASE_PRGRS_STTS_SE_CD IN ('08', '10') THEN CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN 1 END END) AS CASE_TRMN , 'T' AS SXDC_SE_CD , '01' AS SCN_CD FROM X A WHERE CASE_BGNG_YMD <SRT_DT UNION ALL SELECT COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('06') AND AFTFCT_MNG_YN = 'Y' THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('04') THEN CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN 1 END WHEN CASE_PRGRS_STTS_SE_CD IN ('08', '10') THEN CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN 1 END END) AS CASE_TRMN , SXDC_SE_CD , '01' AS SCN_CD FROM X A WHERE CASE_BGNG_YMD <SRT_DT GROUP BY SXDC_SE_CD ) UNION ALL ( /*신규*/ SELECT COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('06') AND AFTFCT_MNG_YN = 'Y' THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('04', '08', '10') THEN 1 END) AS CASE_TRMN , 'T' AS SXDC_SE_CD , '02' AS SCN_CD FROM X A WHERE CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT UNION ALL SELECT COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('06') AND AFTFCT_MNG_YN = 'Y' THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN CASE_PRGRS_STTS_SE_CD IN ('04', '08', '10') THEN 1 END) AS CASE_TRMN , SXDC_SE_CD , '02' AS SCN_CD FROM X A WHERE CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT GROUP BY SXDC_SE_CD ) ) B ON A.CMMNS_CD_VALUE = B.SXDC_SE_CD AND A.SCN_CD = B.SCN_CD

/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectYngbgsCaseMngStatsList[청소년구분별사례관리통계] */ /* Lee SangHoon */
WITH TMP AS ( SELECT A.CD AS CD , B.SXDC_SE_CD AS SX , A.CASE_PRGRS_STTS_SE_CD FROM ( SELECT DISTINCT A.* , REGEXP_SUBSTR(A.YNGBGS_SE_NO, '[^,]+', 1, B.LV) AS CD FROM SEB100 A CROSS JOIN ( SELECT LEVEL AS LV FROM DUAL CONNECT BY LEVEL <= 6 ) B WHERE REGEXP_SUBSTR(A.YNGBGS_SE_NO, '[^,]+', 1, B.LV) IS NOT NULL ) A JOIN SEA200 B ON B.TRPR_INFO_NO = A.TRPR_INFO_NO LEFT JOIN SEB150 F0 ON F0.PCHPRS_YN = 'Y' AND F0.CASE_MNG_NO = A.CASE_MNG_NO AND F0.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO LEFT JOIN SAA000 F3 ON F3.INST_NO = F0.PIC_INST_NO LEFT JOIN AKA500 F4 ON F4.INST_NO = F3.INST_NO
WHERE 1=1 -- 단위업무구분코드 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND B.TRPR_BRTH_YMD IS NULL
-- 연령 기타
-- 청소년쉼터[시설유형구분코드] AND F4.FCLTY_TYPE_SE_CD = #{FCLTY_TYPE_SE_CD}
)
SELECT A.T_NM AS YNGBGS_SE , C.CMMNS_CD_VALUE_NM AS SXDC , NVL(B.CASE_SPRT,0) AS CASE_SPRT , NVL(B.AFTFCT_MNG,0) AS AFTFCT_MNG , NVL(B.CASE_TRMN,0) AS CASE_TRMN FROM ( -- 통계 틀 만들기 SELECT A.CMMNS_CD_VALUE AS T_CD , A.CMMNS_CD_VALUE_NM AS T_NM , A.SRTNG_SQNCE AS T_SN , B.SXDC_SE_CD AS T_SX FROM SAC100 A CROSS JOIN ( SELECT '0T' AS SXDC_SE_CD FROM DUAL UNION SELECT '1M' FROM DUAL UNION SELECT '2F' FROM DUAL UNION SELECT '3X' FROM DUAL ) B WHERE A.CMMNS_CD_ID = 'YNGBGS_STTS_LCLAS_SE_CD' AND A.USE_YN = 'Y' UNION ALL -- 통계 틀 만들기 3(합계) SELECT '00' , '합계' , 0 , SXDC_SE_CD FROM ( SELECT '0T' AS SXDC_SE_CD FROM DUAL UNION SELECT '1M' FROM DUAL UNION SELECT '2F' FROM DUAL UNION SELECT '3X' FROM DUAL ) ) A LEFT JOIN ( SELECT A.CD , A.SX , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('01','02','03','12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('06') THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('04','08','10') THEN 1 END) AS CASE_TRMN FROM TMP A GROUP BY A.CD, A.SX UNION ALL SELECT A.CD , 'T' AS SX , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('01','02','03','12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('06') THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('04','08','10') THEN 1 END) AS CASE_TRMN FROM TMP A GROUP BY A.CD UNION ALL SELECT '00' AS CD , A.SX , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('01','02','03','12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('06') THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('04','08','10') THEN 1 END) AS CASE_TRMN FROM TMP A GROUP BY A.SX UNION ALL SELECT '00' AS CD , 'T' AS SX , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('01','02','03','12') THEN 1 END) AS CASE_SPRT , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('06') THEN 1 END) AS AFTFCT_MNG , COUNT(CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('04','08','10') THEN 1 END) AS CASE_TRMN FROM TMP A ) B ON A.T_CD = B.CD AND SUBSTR(A.T_SX,2,2) = B.SX JOIN ( SELECT CMMNS_CD_VALUE_NM, CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' UNION ALL SELECT '전체' AS CMMNS_CD_VALUE_NM, 'T' AS CMMNS_CD_VALUE FROM DUAL) C ON C.CMMNS_CD_VALUE = SUBSTR(A.T_SX,2,2)
ORDER BY A.T_SN, A.T_SX

/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectProbmSttsCaseMsgStatsList[문제상태별사례관리통계] */ /* Lee HyeSun */
WITH X AS ( SELECT A.CMMNS_CD_VALUE AS LVALUE , A.CMMNS_CD_VALUE_NM AS LNM , B.CMMNS_CD_VALUE AS MVALUE , B.CMMNS_CD_VALUE_NM AS MNM , C.CMMNS_CD_VALUE AS SVALUE , C.CMMNS_CD_VALUE_NM AS SNM FROM ( (SELECT A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM FROM SAC100 A JOIN SAC110 B ON A.CMMNS_CD_ID = B.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A.CMMNS_CD_ID = 'PROBM_STTS_LCLAS_SE_CD' AND A.USE_YN = 'Y' ) A JOIN (SELECT A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM , A.UP_CMMNS_CD_VALUE FROM SAC100 A JOIN SAC110 B ON A.CMMNS_CD_ID = B.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A.CMMNS_CD_ID = 'PROBM_STTS_MLSFC_SE_CD' AND A.USE_YN = 'Y' ) B ON A.CMMNS_CD_VALUE = B.UP_CMMNS_CD_VALUE FULL OUTER JOIN (SELECT A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM , A.UP_CMMNS_CD_VALUE FROM SAC100 A JOIN SAC110 B ON A.CMMNS_CD_ID = B.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A.CMMNS_CD_ID = 'PROBM_STTS_SCLAS_SE_CD' AND A.USE_YN = 'Y' ) C ON B.CMMNS_CD_VALUE = C.UP_CMMNS_CD_VALUE ) UNION ALL SELECT A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM , A.CMMNS_CD_VALUE || '00' , '소계' , NULL , NULL FROM SAC100 A JOIN SAC110 B ON A.CMMNS_CD_ID = B.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A.CMMNS_CD_ID = 'PROBM_STTS_LCLAS_SE_CD' AND A.USE_YN = 'Y'
UNION ALL SELECT '00' , '합계' , NULL , NULL , NULL , NULL FROM SAC100 A JOIN SAC110 B ON A.CMMNS_CD_ID = B.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE )
SELECT X.LVALUE , X.LNM , X.MVALUE , X.MNM , X.SVALUE , X.SNM , NVL(A.CASE1, 0) AS CASE_SPRT /*사례지원중*/ , NVL(A.CASE2, 0) AS AFTFCT_MNG /*사후관리중*/ , NVL(A.CASE3, 0) AS CASE_TRMN /*사례종결*/ FROM ( SELECT LVALUE , LNM , MVALUE , MNM , SVALUE , SNM FROM X ) X LEFT OUTER JOIN ( SELECT NUM , LCLAS , MLSFC , SCLAS , SUM(CASE1) AS CASE1 , SUM(CASE2) AS CASE2 , SUM(CASE3) AS CASE3 FROM ( SELECT '1' AS NUM , '00' AS LCLAS , NULL AS MLSFC , NULL AS SCLAS , CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12') THEN COUNT(COALESCE(NVL(B.PROBM_STTS_SCLAS_SE_CD, 0), NVL(B.PROBM_STTS_MLSFC_SE_CD, 0), NVL(B.PROBM_STTS_LCLAS_SE_CD, 0))) ELSE 0 END AS CASE1 , CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('06') THEN COUNT(COALESCE(NVL(B.PROBM_STTS_SCLAS_SE_CD, 0), NVL(B.PROBM_STTS_MLSFC_SE_CD, 0), NVL(B.PROBM_STTS_LCLAS_SE_CD, 0))) ELSE 0 END AS CASE2 , CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('04', '08', '10') THEN COUNT(COALESCE(NVL(B.PROBM_STTS_SCLAS_SE_CD, 0), NVL(B.PROBM_STTS_MLSFC_SE_CD, 0), NVL(B.PROBM_STTS_LCLAS_SE_CD, 0))) ELSE 0 END AS CASE3 FROM SEB100 A /*사례기본*/ JOIN SEB130 B /*문제상태및원인*/ ON A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO LEFT JOIN SEA200 C /*대상자정보*/ ON A.TRPR_INFO_NO = C.TRPR_INFO_NO AND C.DEL_YN = 'N' JOIN SEB150 F0 /*사례담당자*/ ON A.CASE_MNG_NO = F0.CASE_MNG_NO AND A.CASE_MNG_ODRNO = F0.CASE_MNG_ODRNO AND F0.PCHPRS_YN = 'Y' LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F0.PIC_INST_NO
WHERE 1=1 -- 단위업무구분코드 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND C.TRPR_BRTH_YMD IS NULL
-- 연령 기타
GROUP BY B.PROBM_STTS_LCLAS_SE_CD , B.PROBM_STTS_MLSFC_SE_CD , B.PROBM_STTS_SCLAS_SE_CD , A.CASE_PRGRS_STTS_SE_CD
UNION ALL SELECT '3' AS NUM , B.PROBM_STTS_LCLAS_SE_CD AS LCLAS , B.PROBM_STTS_MLSFC_SE_CD AS MLSFC , B.PROBM_STTS_SCLAS_SE_CD AS SCLAS , CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12') THEN COUNT(COALESCE(NVL(B.PROBM_STTS_SCLAS_SE_CD, 0), NVL(B.PROBM_STTS_MLSFC_SE_CD, 0), NVL(B.PROBM_STTS_LCLAS_SE_CD, 0))) ELSE 0 END AS CASE1 , CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('06') THEN COUNT(COALESCE(NVL(B.PROBM_STTS_SCLAS_SE_CD, 0), NVL(B.PROBM_STTS_MLSFC_SE_CD, 0), NVL(B.PROBM_STTS_LCLAS_SE_CD, 0))) ELSE 0 END AS CASE2 , CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('04', '08', '10') THEN COUNT(COALESCE(NVL(B.PROBM_STTS_SCLAS_SE_CD, 0), NVL(B.PROBM_STTS_MLSFC_SE_CD, 0), NVL(B.PROBM_STTS_LCLAS_SE_CD, 0))) ELSE 0 END AS CASE3
FROM SEB100 A /*사례기본*/ JOIN SEB130 B /*문제상태및원인*/ ON A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO LEFT JOIN SEA200 C /*대상자정보*/ ON A.TRPR_INFO_NO = C.TRPR_INFO_NO AND C.DEL_YN = 'N' JOIN SEB150 F0 /*사례담당자*/ ON A.CASE_MNG_NO = F0.CASE_MNG_NO AND A.CASE_MNG_ODRNO = F0.CASE_MNG_ODRNO AND F0.PCHPRS_YN = 'Y' LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F0.PIC_INST_NO
WHERE 1=1 -- 단위업무구분코드 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND C.TRPR_BRTH_YMD IS NULL
-- 연령 기타
GROUP BY B.PROBM_STTS_LCLAS_SE_CD , B.PROBM_STTS_MLSFC_SE_CD , B.PROBM_STTS_SCLAS_SE_CD , A.CASE_PRGRS_STTS_SE_CD
UNION ALL
SELECT '2' AS NUM , B.PROBM_STTS_LCLAS_SE_CD AS LCLAS , B.PROBM_STTS_LCLAS_SE_CD || '00' AS MLSFC , NULL AS SCLAS , CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12') THEN COUNT(COALESCE(NVL(B.PROBM_STTS_SCLAS_SE_CD, 0), NVL(B.PROBM_STTS_MLSFC_SE_CD, 0), NVL(B.PROBM_STTS_LCLAS_SE_CD, 0))) ELSE 0 END AS CASE1 , CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('06') THEN COUNT(COALESCE(NVL(B.PROBM_STTS_SCLAS_SE_CD, 0), NVL(B.PROBM_STTS_MLSFC_SE_CD, 0), NVL(B.PROBM_STTS_LCLAS_SE_CD, 0))) ELSE 0 END AS CASE2 , CASE WHEN A.CASE_PRGRS_STTS_SE_CD IN ('04', '08', '10') THEN COUNT(COALESCE(NVL(B.PROBM_STTS_SCLAS_SE_CD, 0), NVL(B.PROBM_STTS_MLSFC_SE_CD, 0), NVL(B.PROBM_STTS_LCLAS_SE_CD, 0))) ELSE 0 END AS CASE3 FROM SEB100 A /*사례기본*/ JOIN SEB130 B /*문제상태및원인*/ ON A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO LEFT JOIN SEA200 C /*대상자정보*/ ON A.TRPR_INFO_NO = C.TRPR_INFO_NO AND C.DEL_YN = 'N' JOIN SEB150 F0 /*사례담당자*/ ON A.CASE_MNG_NO = F0.CASE_MNG_NO AND A.CASE_MNG_ODRNO = F0.CASE_MNG_ODRNO AND F0.PCHPRS_YN = 'Y' LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F0.PIC_INST_NO
WHERE 1=1 -- 단위업무구분코드 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND C.TRPR_BRTH_YMD IS NULL
-- 연령 기타
GROUP BY B.PROBM_STTS_LCLAS_SE_CD , B.PROBM_STTS_MLSFC_SE_CD , B.PROBM_STTS_SCLAS_SE_CD , A.CASE_PRGRS_STTS_SE_CD )
GROUP BY LCLAS, MLSFC, SCLAS, NUM ) A ON X.LVALUE = A.LCLAS AND (X.MVALUE = A.MLSFC OR A.MLSFC IS NULL) AND (X.SVALUE = A.SCLAS OR A.SCLAS IS NULL)
WHERE 1=1 GROUP BY X.LVALUE , X.LNM, X.MVALUE, X.MNM, X.SVALUE, X.SNM, NVL(A.CASE1, 0), NVL(A.CASE2, 0), NVL(A.CASE3, 0) ORDER BY X.LVALUE, X.MVALUE, X.SVALUE

/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectSprtSrvcStatsList[지원서비스통계] */ /* Lee Seoung Jae */
WITH TMP AS( SELECT A.SRVC_RESRCE_LCLAS_SE_CD AS SRVC_RESRCE_LCLAS_SE_CD , A.SRVC_RESRCE_MLSFC_SE_CD AS SRVC_RESRCE_MLSFC_SE_CD , A.SRVC_RESRCE_SCLAS_SE_CD AS SRVC_RESRCE_SCLAS_SE_CD , CASE WHEN NVL(CASE WHEN A.SRVC_RESRCE_SCLAS_SE_CD IS NOT NULL THEN COUNT(D.CASE_MNG_NO) END,0) = 0 THEN (CASE WHEN NVL(CASE WHEN A.SRVC_RESRCE_MLSFC_SE_CD IS NOT NULL THEN COUNT(D.CASE_MNG_NO) END,0) = 0 THEN NVL(CASE WHEN A.SRVC_RESRCE_LCLAS_SE_CD IS NOT NULL THEN COUNT(D.CASE_MNG_NO) END,0) ELSE NVL(CASE WHEN A.SRVC_RESRCE_MLSFC_SE_CD IS NOT NULL THEN COUNT(D.CASE_MNG_NO) END,0) END) ELSE NVL(CASE WHEN A.SRVC_RESRCE_SCLAS_SE_CD IS NOT NULL THEN COUNT(D.CASE_MNG_NO) END,0) END AS CNT_CASE_REG
FROM SDA100 A LEFT JOIN SEB500 B ON A.RESRCE_NO = B.RESRCE_NO AND B.DEL_YN != 'Y' LEFT JOIN SEB510 C ON B.SRVC_PVSN_NO = C.SRVC_PVSN_NO AND B.RESRCE_NO = C.RESRCE_NO AND C.DEL_YN != 'Y' LEFT JOIN SEB100 D ON C.CASE_MNG_NO = D.CASE_MNG_NO AND C.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO LEFT JOIN ( SELECT CASE_MNG_NO , CASE_MNG_ODRNO , CASE_PIC_NO , PIC_INST_NO , ROW_NUMBER() OVER(PARTITION BY CASE_MNG_NO, CASE_MNG_ODRNO ORDER BY CASE_MNG_NO, CASE_MNG_ODRNO) AS RN FROM SEB150 ) F0 ON D.CASE_MNG_NO = F0.CASE_MNG_NO AND D.CASE_MNG_ODRNO = F0.CASE_MNG_ODRNO LEFT JOIN SAA000 G ON F0.PIC_INST_NO = G.INST_NO AND G.DEL_YN != 'Y' LEFT JOIN SAA020 H ON G.SGG_CD = H.SGG_CD AND H.DEL_YN != 'Y' WHERE 1=1 -- 단위업무구분코드 AND (G.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}) -- 기간구분 AND B.SRVC_PVSN_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
/* 20230622_이승재_권한에 따른 담당자 행번호 결정 시작(아래조건 만족시 RN=1 그 외는 담당자)*/
/*ROW NUM 첫번째항목만 출력*/ AND F0.RN = 1
/* 20230622_이승재_권한에 따른 담당자 행번호 결정 종료*/
-- 시도코드 AND G.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND G.SGG_CD = #{SGG_CD}
-- 기관번호 AND G.INST_NO = #{INST_NO}
GROUP BY A.SRVC_RESRCE_LCLAS_SE_CD, A.SRVC_RESRCE_MLSFC_SE_CD, A.SRVC_RESRCE_SCLAS_SE_CD ORDER BY A.SRVC_RESRCE_LCLAS_SE_CD, A.SRVC_RESRCE_MLSFC_SE_CD, A.SRVC_RESRCE_SCLAS_SE_CD ) --소계
, TMPSUM AS ( SELECT NVL2(A.SRVC_RESRCE_LCLAS_SE_CD, A.SRVC_RESRCE_LCLAS_SE_CD, '00') AS SRVC_RESRCE_LCLAS_SE_CD , '0000' AS SRVC_RESRCE_MLSFC_SE_CD , '000000' AS SRVC_RESRCE_SCLAS_SE_CD , COUNT(D.CASE_MNG_NO) AS CNT_CASE_REG
FROM SDA100 A LEFT JOIN SEB500 B ON A.RESRCE_NO = B.RESRCE_NO AND B.DEL_YN != 'Y' LEFT JOIN SEB510 C ON B.SRVC_PVSN_NO = C.SRVC_PVSN_NO AND B.RESRCE_NO = C.RESRCE_NO AND C.DEL_YN != 'Y' LEFT JOIN SEB100 D ON C.CASE_MNG_NO = D.CASE_MNG_NO AND C.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO LEFT JOIN ( SELECT CASE_MNG_NO , CASE_MNG_ODRNO , CASE_PIC_NO , PIC_INST_NO , ROW_NUMBER() OVER(PARTITION BY CASE_MNG_NO, CASE_MNG_ODRNO ORDER BY CASE_MNG_NO, CASE_MNG_ODRNO) AS RN FROM SEB150 ) F0 ON D.CASE_MNG_NO = F0.CASE_MNG_NO AND D.CASE_MNG_ODRNO = F0.CASE_MNG_ODRNO LEFT JOIN SAA000 G ON F0.PIC_INST_NO = G.INST_NO AND G.DEL_YN != 'Y' LEFT JOIN SAA020 H ON G.SGG_CD = H.SGG_CD AND H.DEL_YN != 'Y' WHERE 1=1 AND A.SRVC_RESRCE_LCLAS_SE_CD != '*' -- 단위업무구분코드 AND (G.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}) -- 기간구분 AND B.SRVC_PVSN_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
/* 20230622_이승재_권한에 따른 담당자 행번호 결정 시작(아래조건 만족시 RN=1 그 외는 담당자)*/
/*ROW NUM 첫번째항목만 출력*/ AND F0.RN = 1
/* 20230622_이승재_권한에 따른 담당자 행번호 결정 종료*/
-- 시도코드 AND G.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND G.SGG_CD = #{SGG_CD}
-- 기관번호 AND G.INST_NO = #{INST_NO}
GROUP BY GROUPING SETS(A.SRVC_RESRCE_LCLAS_SE_CD,()) ORDER BY SRVC_RESRCE_LCLAS_SE_CD )
--나타낼 데이터 쿼리 SELECT CASE WHEN SRVC_RESRCE_LCLAS_SE_CD = '00' THEN '합계' ELSE SRVC_RESRCE_LCLAS_SE_NM END AS SRVC_RESRCE_LCLAS_SE_NM , CASE WHEN SRVC_RESRCE_MLSFC_SE_CD = '0000' THEN '소계' ELSE SRVC_RESRCE_MLSFC_SE_NM END AS SRVC_RESRCE_MLSFC_SE_NM , CASE WHEN SRVC_RESRCE_SCLAS_SE_CD = '000000' THEN '소계' ELSE SRVC_RESRCE_SCLAS_SE_NM END AS SRVC_RESRCE_SCLAS_SE_NM , SRVC_RESRCE_LCLAS_SE_CD , SRVC_RESRCE_MLSFC_SE_CD , SRVC_RESRCE_SCLAS_SE_CD , CNT_CASE_REG , CNT_CASE_UNREGI FROM (SELECT A.SRVC_RESRCE_LCLAS_SE_NM , A.SRVC_RESRCE_MLSFC_SE_NM , A.SRVC_RESRCE_SCLAS_SE_NM , A.SRVC_RESRCE_LCLAS_SE_CD , A.SRVC_RESRCE_MLSFC_SE_CD , A.SRVC_RESRCE_SCLAS_SE_CD , NVL(B.CNT_CASE_REG,0) AS CNT_CASE_REG , NVL(C.CNT_CASE_UNREGI, 0) AS CNT_CASE_UNREGI FROM ( -- 통계 틀 만들기 SELECT DISTINCT A.CMMNS_CD_VALUE_NM AS SRVC_RESRCE_LCLAS_SE_NM , B.CMMNS_CD_VALUE_NM AS SRVC_RESRCE_MLSFC_SE_NM , C.CMMNS_CD_VALUE_NM AS SRVC_RESRCE_SCLAS_SE_NM , A.CMMNS_CD_VALUE AS SRVC_RESRCE_LCLAS_SE_CD , B.CMMNS_CD_VALUE AS SRVC_RESRCE_MLSFC_SE_CD , C.CMMNS_CD_VALUE AS SRVC_RESRCE_SCLAS_SE_CD FROM SAC100 A LEFT JOIN SAC110 D ON D.CMMNS_CD_ID = A.CMMNS_CD_ID LEFT JOIN ( SELECT DISTINCT B.CMMNS_CD_VALUE_NM , B.CMMNS_CD_VALUE , B.UP_CMMNS_CD_VALUE FROM SAC100 B JOIN SAC110 C ON B.CMMNS_CD_ID = C.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = C.CMMNS_CD_VALUE AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE B.CMMNS_CD_ID = 'SRVC_RESRCE_MLSFC_SE_CD' ORDER BY B.CMMNS_CD_VALUE ) B ON A.CMMNS_CD_VALUE = B.UP_CMMNS_CD_VALUE LEFT JOIN ( SELECT DISTINCT B.CMMNS_CD_VALUE_NM , B.CMMNS_CD_VALUE , B.UP_CMMNS_CD_VALUE FROM SAC100 B JOIN SAC110 C ON B.CMMNS_CD_ID = C.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = C.CMMNS_CD_VALUE AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE B.CMMNS_CD_ID = 'SRVC_RESRCE_SCLAS_SE_CD' ORDER BY B.CMMNS_CD_VALUE ) C ON B.CMMNS_CD_VALUE = C.UP_CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} ORDER BY A.CMMNS_CD_VALUE, B.CMMNS_CD_VALUE, C.CMMNS_CD_VALUE ) A LEFT JOIN TMP B ON A.SRVC_RESRCE_LCLAS_SE_CD = B.SRVC_RESRCE_LCLAS_SE_CD AND (A.SRVC_RESRCE_MLSFC_SE_CD = B.SRVC_RESRCE_MLSFC_SE_CD OR B.SRVC_RESRCE_MLSFC_SE_CD IS NULL) AND (A.SRVC_RESRCE_SCLAS_SE_CD = B.SRVC_RESRCE_SCLAS_SE_CD OR B.SRVC_RESRCE_SCLAS_SE_CD IS NULL)
--미등록사례지원 LEFT JOIN ( SELECT SUM(NVL(ELESCH_STDENT_MALE_NOPE,0) + NVL(ELESCH_STDENT_FEMALE_NOPE,0) + NVL(MSKUL_STDENT_MALE_NOPE,0) + NVL(MSKUL_STDENT_FEMALE_NOPE,0) + NVL(HGSCHL_STDENT_MALE_NOPE,0) + NVL(HGSCHL_STDENT_FEMALE_NOPE,0) + NVL(UNIVA_STDENT_MALE_NOPE,0) + NVL(UNIVA_STDENT_FEMALE_NOPE,0) + NVL(ELESCH_OSCHL_MALE_NOPE,0) + NVL(ELESCH_OSCHL_FEMALE_NOPE,0) + NVL(MSKUL_OSCHL_MALE_NOPE,0) + NVL(MSKUL_OSCHL_FEMALE_NOPE,0) + NVL(HGSCHL_OSCHL_MALE_NOPE,0) + NVL(HGSCHL_OSCHL_FEMALE_NOPE,0) + NVL(UNIVA_OSCHL_MALE_NOPE,0) + NVL(UNIVA_OSCHL_FEMALE_NOPE,0) + NVL(AGRDHS_IOCPTN_MALE_NOPE,0) + NVL(AGRDHS_EMPYMN_MALE_NOPE,0) + NVL(AGRDHS_IOCPTN_FEMALE_NOPE,0) + NVL(AGRDHS_EMPYMN_FEMALE_NOPE,0) + NVL(PARNTS_PRTCR_MALE_NOPE,0) + NVL(LEADER_MALE_NOPE,0) + NVL(PEPL_MALE_NOPE,0) + NVL(PARNTS_PRTCR_FEMALE_NOPE,0) + NVL(LEADER_FEMALE_NOPE,0) + NVL(PEPL_FEMALE_NOPE,0)) AS CNT_CASE_UNREGI ,A.SRVC_RESRCE_LCLAS_SE_CD, A.SRVC_RESRCE_MLSFC_SE_CD, A.SRVC_RESRCE_SCLAS_SE_CD FROM SED100 A JOIN SAA000 BB ON A.PIC_INST_NO = BB.INST_NO JOIN SCA100 CC ON A.PIC_NO = CC.ENFSN_NO
WHERE BB.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND BB.DEL_YN = 'N' AND CC.DEL_YN = 'N'
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 기간구분 AND A.SPRT_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
-- 시도코드 AND BB.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND BB.SGG_CD = #{SGG_CD}
-- 기관번호 AND BB.INST_NO = #{INST_NO}
GROUP BY A.SRVC_RESRCE_LCLAS_SE_CD, A.SRVC_RESRCE_MLSFC_SE_CD, A.SRVC_RESRCE_SCLAS_SE_CD ORDER BY A.SRVC_RESRCE_LCLAS_SE_CD, A.SRVC_RESRCE_MLSFC_SE_CD, A.SRVC_RESRCE_SCLAS_SE_CD) C ON A.SRVC_RESRCE_LCLAS_SE_CD = C.SRVC_RESRCE_LCLAS_SE_CD AND (A.SRVC_RESRCE_MLSFC_SE_CD = C.SRVC_RESRCE_MLSFC_SE_CD OR C.SRVC_RESRCE_MLSFC_SE_CD IS NULL) AND (A.SRVC_RESRCE_SCLAS_SE_CD = C.SRVC_RESRCE_SCLAS_SE_CD OR C.SRVC_RESRCE_SCLAS_SE_CD IS NULL)
ORDER BY A.SRVC_RESRCE_LCLAS_SE_CD, A.SRVC_RESRCE_MLSFC_SE_CD, A.SRVC_RESRCE_SCLAS_SE_CD)
UNION ALL
--소계
SELECT A.SRVC_RESRCE_LCLAS_SE_NM , '소계' , '' , A.SRVC_RESRCE_LCLAS_SE_CD , A.SRVC_RESRCE_MLSFC_SE_CD , A.SRVC_RESRCE_SCLAS_SE_CD , NVL(B.CNT_CASE_REG,0) , NVL(C.CNT_CASE_UNREGI ,0) FROM ( SELECT DISTINCT A.CMMNS_CD_VALUE_NM AS SRVC_RESRCE_LCLAS_SE_NM , A.CMMNS_CD_VALUE AS SRVC_RESRCE_LCLAS_SE_CD , '0000' AS SRVC_RESRCE_MLSFC_SE_CD , '000000' AS SRVC_RESRCE_SCLAS_SE_CD FROM SAC100 A LEFT JOIN SAC110 D ON D.CMMNS_CD_ID = A.CMMNS_CD_ID LEFT JOIN ( SELECT DISTINCT B.CMMNS_CD_VALUE_NM , B.CMMNS_CD_VALUE , B.UP_CMMNS_CD_VALUE FROM SAC100 B JOIN SAC110 C ON B.CMMNS_CD_ID = C.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = C.CMMNS_CD_VALUE AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE B.CMMNS_CD_ID = 'SRVC_RESRCE_MLSFC_SE_CD' ORDER BY B.CMMNS_CD_VALUE ) B ON A.CMMNS_CD_VALUE = B.UP_CMMNS_CD_VALUE LEFT JOIN ( SELECT DISTINCT B.CMMNS_CD_VALUE_NM , B.CMMNS_CD_VALUE , B.UP_CMMNS_CD_VALUE FROM SAC100 B JOIN SAC110 C ON B.CMMNS_CD_ID = C.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = C.CMMNS_CD_VALUE AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE B.CMMNS_CD_ID = 'SRVC_RESRCE_SCLAS_SE_CD' ORDER BY B.CMMNS_CD_VALUE ) C ON B.CMMNS_CD_VALUE = C.UP_CMMNS_CD_VALUE
WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
UNION ALL
SELECT '합계' , '00' , '0000' , '000000' FROM DUAL
) A LEFT JOIN ( SELECT (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND CMMNS_CD_VALUE = SRVC_RESRCE_LCLAS_SE_CD) AS SRVC_RESRCE_LCLAS_SE_NM , '소계' AS SRVC_RESRCE_MLSFC_SE_NM , '' AS SRVC_RESRCE_SCLAS_SE_NM , SRVC_RESRCE_LCLAS_SE_CD , SRVC_RESRCE_MLSFC_SE_CD , SRVC_RESRCE_SCLAS_SE_CD , CNT_CASE_REG AS CNT_CASE_REG FROM TMPSUM WHERE SRVC_RESRCE_LCLAS_SE_CD IN(00,01,02,03,04,05,06,07,08,09,10,11) )B ON (A.SRVC_RESRCE_LCLAS_SE_CD = B.SRVC_RESRCE_LCLAS_SE_CD)
--미등록사례지원 LEFT JOIN ( SELECT NVL2(A.SRVC_RESRCE_LCLAS_SE_CD, A.SRVC_RESRCE_LCLAS_SE_CD, '00') AS SRVC_RESRCE_LCLAS_SE_CD , '0000' AS SRVC_RESRCE_MLSFC_SE_CD , '000000' AS SRVC_RESRCE_SCLAS_SE_CD , SUM(NVL(ELESCH_STDENT_MALE_NOPE,0) + NVL(ELESCH_STDENT_FEMALE_NOPE,0) + NVL(MSKUL_STDENT_MALE_NOPE,0) + NVL(MSKUL_STDENT_FEMALE_NOPE,0) + NVL(HGSCHL_STDENT_MALE_NOPE,0) + NVL(HGSCHL_STDENT_FEMALE_NOPE,0) + NVL(UNIVA_STDENT_MALE_NOPE,0) + NVL(UNIVA_STDENT_FEMALE_NOPE,0) + NVL(ELESCH_OSCHL_MALE_NOPE,0) + NVL(ELESCH_OSCHL_FEMALE_NOPE,0) + NVL(MSKUL_OSCHL_MALE_NOPE,0) + NVL(MSKUL_OSCHL_FEMALE_NOPE,0) + NVL(HGSCHL_OSCHL_MALE_NOPE,0) + NVL(HGSCHL_OSCHL_FEMALE_NOPE,0) + NVL(UNIVA_OSCHL_MALE_NOPE,0) + NVL(UNIVA_OSCHL_FEMALE_NOPE,0) + NVL(AGRDHS_IOCPTN_MALE_NOPE,0) + NVL(AGRDHS_EMPYMN_MALE_NOPE,0) + NVL(AGRDHS_IOCPTN_FEMALE_NOPE,0) + NVL(AGRDHS_EMPYMN_FEMALE_NOPE,0) + NVL(PARNTS_PRTCR_MALE_NOPE,0) + NVL(LEADER_MALE_NOPE,0) + NVL(PEPL_MALE_NOPE,0) + NVL(PARNTS_PRTCR_FEMALE_NOPE,0) + NVL(LEADER_FEMALE_NOPE,0) + NVL(PEPL_FEMALE_NOPE,0)) AS CNT_CASE_UNREGI FROM SED100 A JOIN SAA000 BB ON A.PIC_INST_NO = BB.INST_NO JOIN SCA100 CC ON A.PIC_NO = CC.ENFSN_NO
WHERE BB.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND BB.DEL_YN = 'N' AND CC.DEL_YN = 'N' -- 기간구분 AND A.SPRT_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND BB.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND BB.SGG_CD = #{SGG_CD}
-- 기관번호 AND BB.INST_NO = #{INST_NO}
GROUP BY GROUPING SETS(A.SRVC_RESRCE_LCLAS_SE_CD,()) ORDER BY SRVC_RESRCE_LCLAS_SE_CD) C ON A.SRVC_RESRCE_LCLAS_SE_CD = C.SRVC_RESRCE_LCLAS_SE_CD
ORDER BY SRVC_RESRCE_LCLAS_SE_CD, SRVC_RESRCE_MLSFC_SE_CD, SRVC_RESRCE_SCLAS_SE_CD

/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectOutStatsPubmsList[성과통계(쉼터)] */ /* Park SeongWon */
WITH TMP AS( SELECT OUTC_CN_LCLAS_SE_CD , OUTC_CN_MLSFC_SE_CD , OUTC_CN_SCLAS_SE_CD , COUNT(C.TRPR_INFO_NO) AS CASE_TOT_CNT , COUNT(DISTINCT NVL(C.INDV_IDNTFC_NO, C.TRPR_INFO_NO)) AS IDNO_CNT FROM SEB100 A LEFT JOIN AKA130 B ON A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO LEFT JOIN SEA200 C ON A.TRPR_INFO_NO = C.TRPR_INFO_NO LEFT JOIN SEB150 F0 ON F0.PCHPRS_YN = 'Y' AND F0.CASE_MNG_NO = A.CASE_MNG_NO AND F0.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO LEFT JOIN SAA000 F3 ON F3.INST_NO = F0.PIC_INST_NO LEFT JOIN AKA500 F4 ON F4.INST_NO = F3.INST_NO
WHERE 1=1 AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND B.USE_YN = 'Y'
-- 기간구분 AND B.OUTC_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND C.TRPR_BRTH_YMD IS NULL
-- 연령 기타
-- 청소년쉼터[시설유형구분코드] AND F4.FCLTY_TYPE_SE_CD = #{FCLTY_TYPE_SE_CD}
GROUP BY OUTC_CN_LCLAS_SE_CD, OUTC_CN_MLSFC_SE_CD, OUTC_CN_SCLAS_SE_CD, C.INDV_IDNTFC_NO )
SELECT T_NM AS OUTC_CN_LCLAS_NM , T_NM2 AS OUTC_CN_MLSFC_NM , T_NM3 AS OUTC_CN_SCLAS_NM , NVL(CASE_TOT_CNT, 0) AS CASE_TOT_CNT , NVL(IDNO_CNT, 0) AS IDNO_CNT FROM ( -- 통계틀 만들기 SELECT A.CMMNS_CD_VALUE AS T_CD , A2.CMMNS_CD_VALUE AS T_CD2 , A3.CMMNS_CD_VALUE AS T_CD3 , A.CMMNS_CD_VALUE_NM AS T_NM , A2.CMMNS_CD_VALUE_NM AS T_NM2 , A3.CMMNS_CD_VALUE_NM AS T_NM3 , A.SRTNG_SQNCE AS T_SN , A2.SRTNG_SQNCE AS T_SN2 , A3.SRTNG_SQNCE AS T_SN3
FROM SAC100 A JOIN SAC110 B ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} LEFT JOIN ( SELECT A2.* FROM SAC100 A2 JOIN SAC110 B2 ON B2.CMMNS_CD_ID = A2.CMMNS_CD_ID AND B2.CMMNS_CD_VALUE = A2.CMMNS_CD_VALUE AND B2.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A2.CMMNS_CD_ID = 'OUTC_CN_MLSFC_SE_CD' AND A2.USE_YN = 'Y' ) A2 ON A2.UP_CMMNS_CD_VALUE = A.CMMNS_CD_VALUE LEFT JOIN ( SELECT A3.* FROM SAC100 A3 JOIN SAC110 B3 ON B3.CMMNS_CD_ID = A3.CMMNS_CD_ID AND B3.CMMNS_CD_VALUE = A3.CMMNS_CD_VALUE AND B3.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A3.CMMNS_CD_ID = 'OUTC_CN_SCLAS_SE_CD' AND A3.USE_YN = 'Y' ) A3 ON A3.UP_CMMNS_CD_VALUE = A2.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'OUTC_CN_LCLAS_SE_CD' AND A.USE_YN = 'Y' UNION ALL SELECT A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE || '00' , NULL , A.CMMNS_CD_VALUE_NM , '소계' , NULL , A.SRTNG_SQNCE , 0 , NULL FROM SAC100 A JOIN SAC110 B ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A.CMMNS_CD_ID = 'OUTC_CN_LCLAS_SE_CD' UNION ALL SELECT '00' , '00' , NULL , '합계' , NULL , NULL , 0 , NULL , NULL FROM DUAL ) A LEFT JOIN ( SELECT OUTC_CN_LCLAS_SE_CD , OUTC_CN_MLSFC_SE_CD , OUTC_CN_SCLAS_SE_CD , SUM(CASE_TOT_CNT) AS CASE_TOT_CNT , SUM(IDNO_CNT) AS IDNO_CNT FROM TMP GROUP BY OUTC_CN_LCLAS_SE_CD, OUTC_CN_MLSFC_SE_CD, OUTC_CN_SCLAS_SE_CD UNION ALL SELECT OUTC_CN_LCLAS_SE_CD , OUTC_CN_LCLAS_SE_CD || '00' , NULL , SUM(CASE_TOT_CNT) AS CASE_TOT_CNT , SUM(IDNO_CNT) AS IDNO_CNT FROM TMP GROUP BY OUTC_CN_LCLAS_SE_CD UNION ALL SELECT '00' , '00' , NULL , SUM(CASE_TOT_CNT) AS CASE_TOT_CNT , SUM(IDNO_CNT) AS IDNO_CNT FROM TMP ) B ON OUTC_CN_LCLAS_SE_CD = T_CD AND ( OUTC_CN_MLSFC_SE_CD = T_CD2 OR OUTC_CN_MLSFC_SE_CD IS NULL ) AND ( OUTC_CN_SCLAS_SE_cD = T_CD3 OR OUTC_CN_SCLAS_SE_CD IS NULL )
ORDER BY T_SN, T_SN2, T_SN3

/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectOutStatsPubmtList[성과통계(자립지원관)] */ /* Lee SangHoon */
WITH TMP AS( SELECT OUTC_CN_LCLAS_SE_CD , OUTC_CN_MLSFC_SE_CD , OUTC_CN_SCLAS_SE_CD , COUNT(B.TRPR_INFO_NO) AS CASE_TOT_CNT , CASE WHEN B.INDV_IDNTFC_NO IS NULL THEN COUNT(1) ELSE COUNT(1) - COUNT(1) + 1 END AS IDNO_CNT FROM SEB100 A LEFT JOIN SEA200 B ON B.TRPR_INFO_NO = A.TRPR_INFO_NO JOIN AKA130 C ON C.CASE_MNG_NO = A.CASE_MNG_NO AND C.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO LEFT JOIN SEB150 F0 ON F0.PCHPRS_YN = 'Y' AND F0.CASE_MNG_NO = A.CASE_MNG_NO AND F0.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO LEFT JOIN SAA000 F3 ON F3.INST_NO = F0.PIC_INST_NO
WHERE 1=1 -- 단위업무구분코드 AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,B.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND B.TRPR_BRTH_YMD IS NULL
-- 연령 기타
GROUP BY OUTC_CN_LCLAS_SE_CD, OUTC_CN_MLSFC_SE_CD, OUTC_CN_SCLAS_SE_CD, B.INDV_IDNTFC_NO )
SELECT T_NM AS OUTC_CN_LCLAS_NM , T_NM2 AS OUTC_CN_MLSFC_NM , T_NM3 AS OUTC_CN_SCLAS_NM , NVL(CASE_TOT_CNT,0) AS NMPR , NVL(IDNO_CNT,0) AS REAL_NMPR FROM ( SELECT A.CMMNS_CD_VALUE AS T_CD , A2.CMMNS_CD_VALUE AS T_CD2 , A3.CMMNS_CD_VALUE AS T_CD3 , A.CMMNS_CD_VALUE_NM AS T_NM , A2.CMMNS_CD_VALUE_NM AS T_NM2 , A3.CMMNS_CD_VALUE_NM AS T_NM3 , A.SRTNG_SQNCE AS T_SN , A2.SRTNG_SQNCE AS T_SN2 , A3.SRTNG_SQNCE AS T_SN3 FROM SAC100 A JOIN SAC110 B ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} LEFT JOIN ( SELECT A2.* FROM SAC100 A2 JOIN SAC110 B2 ON B2.CMMNS_CD_ID = A2.CMMNS_CD_ID AND B2.CMMNS_CD_VALUE = A2.CMMNS_CD_VALUE AND B2.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A2.CMMNS_CD_ID = 'OUTC_CN_MLSFC_SE_CD' AND A2.USE_YN = 'Y' ) A2 ON A2.UP_CMMNS_CD_VALUE = A.CMMNS_CD_VALUE LEFT JOIN ( SELECT A3.* FROM SAC100 A3 JOIN SAC110 B3 ON B3.CMMNS_CD_ID = A3.CMMNS_CD_ID AND B3.CMMNS_CD_VALUE = A3.CMMNS_CD_VALUE AND B3.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A3.CMMNS_CD_ID = 'OUTC_CN_SCLAS_SE_CD' AND A3.USE_YN = 'Y' ) A3 ON A3.UP_CMMNS_CD_VALUE = A2.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'OUTC_CN_LCLAS_SE_CD' AND A.USE_YN = 'Y' UNION ALL SELECT '00' , NULL , NULL , '합계' , NULL , NULL , 0 , NULL , NULL FROM DUAL ) A LEFT JOIN ( SELECT OUTC_CN_LCLAS_SE_CD , OUTC_CN_MLSFC_SE_CD , OUTC_CN_SCLAS_SE_CD , SUM(CASE_TOT_CNT) AS CASE_TOT_CNT , SUM(IDNO_CNT) AS IDNO_CNT FROM TMP GROUP BY OUTC_CN_LCLAS_SE_CD, OUTC_CN_MLSFC_SE_CD, OUTC_CN_SCLAS_SE_CD UNION ALL SELECT '00' , NULL , NULL , SUM(CASE_TOT_CNT) AS CASE_TOT_CNT , SUM(IDNO_CNT) AS IDNO_CNT FROM TMP ) B ON OUTC_CN_LCLAS_SE_CD = T_CD AND (OUTC_CN_MLSFC_SE_CD = T_CD2 OR OUTC_CN_MLSFC_SE_CD IS NULL) AND (OUTC_CN_SCLAS_SE_CD = T_CD3 OR OUTC_CN_SCLAS_SE_CD IS NULL)
ORDER BY T_SN, T_SN2, T_SN3

/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectDscsnOutrcMngStatsList[아웃리치통계(쉼터)] */ /* Lee SangHoon */
WITH TMP AS ( SELECT A1.* , A2.* , A3.* , A4.* , B.FCLTY_TYPE_SE_CD FROM SEA120 A1 LEFT JOIN ( SELECT ERYY_GR_DSCSN_NO , UNEART_ACTVT_CL_SE_CD , SUM(UNEART_ACTVT_PIC_CNT) AS UNEART_ACTVT_PIC_CNT FROM SEA140 GROUP BY ERYY_GR_DSCSN_NO, UNEART_ACTVT_CL_SE_CD ) A2 ON A2.ERYY_GR_DSCSN_NO = A1.ERYY_GR_DSCSN_NO LEFT JOIN ( SELECT ERYY_GR_DSCSN_NO , SUM(TRL_INSP) AS TRL_INSP , SUM(MDLRT_SPRT) AS MDLRT_SPRT , SUM(MEDICI_SPRT) AS MEDICI_SPRT , SUM(CLTH_SPRT) AS CLTH_SPRT , SUM(SNITAT_SPRT) AS SNITAT_SPRT , SUM(FDSTFA_SPRT) AS FDSTFA_SPRT , SUM(MVMN_SPRT) AS MVMN_SPRT , SUM(REST_SPRT) AS REST_SPRT , SUM(LVING_SUPLI_SPRT) AS LVING_SUPLI_SPRT , SUM(INFO_PVSN) AS INFO_PVSN , SUM(LVM_YNGBGS_DSCSN) AS LVM_YNGBGS_DSCSN , SUM(DSCSN_ETC) AS DSCSN_ETC , SUM(SRVC_SPRT_CNT_ETC) AS SRVC_SPRT_CNT_ETC FROM SEA150 PIVOT ( SUM(SPRT_SRVC_TRGT_NOPE) FOR SPRT_SRVC_SE_CD IN ( '01' AS TRL_INSP , '02' AS MDLRT_SPRT , '03' AS MEDICI_SPRT , '04' AS CLTH_SPRT , '05' AS SNITAT_SPRT , '06' AS FDSTFA_SPRT , '07' AS MVMN_SPRT , '08' AS REST_SPRT , '09' AS LVING_SUPLI_SPRT , '10' AS INFO_PVSN , '97' AS LVM_YNGBGS_DSCSN , '98' AS DSCSN_ETC , '99' AS SRVC_SPRT_CNT_ETC ) ) GROUP BY ERYY_GR_DSCSN_NO ) A3 ON A3.ERYY_GR_DSCSN_NO = A1.ERYY_GR_DSCSN_NO LEFT JOIN ( SELECT A41.ERYY_GR_DSCSN_NO , COUNT(CASE WHEN A42.SXDC_SE_CD = 'M' THEN 1 END) AS ACTN_NOPE_MALE , COUNT(CASE WHEN A42.SXDC_SE_CD = 'F' THEN 1 END) AS ACTN_NOPE_FEMALE , COUNT(CASE WHEN A41.ACTN_TYPE_SE_CD = '01' THEN 1 END) AS HMCM , COUNT(CASE WHEN A41.ACTN_TYPE_DTL_SE_CD = '01' THEN 1 END) AS SHELTR , COUNT(CASE WHEN A41.ACTN_TYPE_DTL_SE_CD = '02' THEN 1 END) AS OTSHTR , COUNT(CASE WHEN A41.ACTN_TYPE_DTL_SE_CD = '03' THEN 1 END) AS EMRG_RESC , COUNT(CASE WHEN A41.ACTN_TYPE_DTL_SE_CD = '04' THEN 1 END) AS OTFCLT , COUNT(CASE WHEN A41.ACTN_TYPE_DTL_SE_CD = '05' THEN 1 END) AS OTHNST , COUNT(CASE WHEN A41.ACTN_TYPE_SE_CD = '99' THEN 1 END) AS ACTN_MATTER_ETC FROM SEA130 A41 JOIN SEA200 A42 ON A41.TRPR_INFO_NO = A42.TRPR_INFO_NO GROUP BY A41.ERYY_GR_DSCSN_NO ) A4 ON A4.ERYY_GR_DSCSN_NO = A1.ERYY_GR_DSCSN_NO JOIN AKA500 B ON B.INST_NO = A1.RGTR_INST_NO LEFT JOIN SAA000 F3 ON F3.INST_NO = A1.RGTR_INST_NO
WHERE 1=1 -- 단위업무구분코드 AND A1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A1.DSCSN_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
)
SELECT T_NM AS TYPE_SE , NVL(OFFLINE_NOPE,0) AS OFFLINE_NOPE , NVL(ONLINE_NOPE,0) AS ONLINE_NOPE , NVL(DSTNC_DSCSN_CNT,0) AS DSTNC_DSCSN_CNT , NVL(DSTNC_DSCSN_NOPE,0) AS DSTNC_DSCSN_NOPE , NVL(SHELTR_ONSLF_ACTVT_CNT,0) AS SHELTR_ONSLF_ACTVT_CNT , NVL(SHELTR_ONSLF_ACTVT_NOPE,0) AS SHELTR_ONSLF_ACTVT_NOPE , NVL(ERYY_DSCSN_MALE_NOPE,0) AS ERYY_DSCSN_MALE_NOPE , NVL(ERYY_DSCSN_FEMALE_NOPE,0) AS ERYY_DSCSN_FEMALE_NOPE , NVL(LVM_YNGBGS_DSCSN,0) AS LVM_YNGBGS_DSCSN , NVL(DSCSN_ETC,0) AS DSCSN_ETC , NVL(TRL_INSP,0) AS TRL_INSP , NVL(MDLRT_SPRT,0) AS MDLRT_SPRT , NVL(MEDICI_SPRT,0) AS MEDICI_SPRT , NVL(CLTH_SPRT,0) AS CLTH_SPRT , NVL(SNITAT_SPRT,0) AS SNITAT_SPRT , NVL(FDSTFA_SPRT,0) AS FDSTFA_SPRT , NVL(MVMN_SPRT,0) AS MVMN_SPRT , NVL(REST_SPRT,0) AS REST_SPRT , NVL(LVING_SUPLI_SPRT,0) AS LVING_SUPLI_SPRT , NVL(INFO_PVSN,0) AS INFO_PVSN , NVL(SRVC_SPRT_CNT_ETC,0) AS SRVC_SPRT_CNT_ETC , NVL(ACTN_NOPE_MALE,0) AS ACTN_NOPE_MALE , NVL(ACTN_NOPE_FEMALE,0) AS ACTN_NOPE_FEMALE , NVL(HMCM,0) AS HMCM , NVL(SHELTR,0) AS SHELTR , NVL(OTSHTR,0) AS OTSHTR , NVL(EMRG_RESC,0) AS EMRG_RESC , NVL(OTFCLT,0) AS OTFCLT , NVL(OTHNST,0) AS OTHNST , NVL(ACTN_MATTER_ETC,0) AS ACTN_MATTER_ETC FROM ( SELECT A.CMMNS_CD_VALUE AS T_CD , A.CMMNS_CD_VALUE_NM AS T_NM , A.SRTNG_SQNCE AS T_SN FROM SAC100 A JOIN SAC110 B ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A.CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND A.USE_YN = 'Y' UNION ALL SELECT '00' , '합계' , 0 FROM DUAL ) A LEFT JOIN ( SELECT FCLTY_TYPE_SE_CD , COUNT(CASE WHEN UNEART_ACTVT_MTHD_SE_CD = '1' THEN 1 END) AS OFFLINE_NOPE , COUNT(CASE WHEN UNEART_ACTVT_MTHD_SE_CD = '2' THEN 1 END) AS ONLINE_NOPE , COUNT(CASE WHEN UNEART_ACTVT_CL_SE_CD = '1' THEN 1 END) AS DSTNC_DSCSN_CNT , SUM(CASE WHEN UNEART_ACTVT_CL_SE_CD = '1' THEN UNEART_ACTVT_PIC_CNT END) AS DSTNC_DSCSN_NOPE , COUNT(CASE WHEN UNEART_ACTVT_CL_SE_CD = '2' THEN 1 END) AS SHELTR_ONSLF_ACTVT_CNT , SUM(CASE WHEN UNEART_ACTVT_CL_SE_CD = '2' THEN UNEART_ACTVT_PIC_CNT END) AS SHELTR_ONSLF_ACTVT_NOPE , SUM(ERYY_DSCSN_MALE_NOPE) AS ERYY_DSCSN_MALE_NOPE , SUM(ERYY_DSCSN_FEMALE_NOPE) AS ERYY_DSCSN_FEMALE_NOPE , SUM(LVM_YNGBGS_DSCSN) AS LVM_YNGBGS_DSCSN , SUM(DSCSN_ETC) AS DSCSN_ETC , SUM(TRL_INSP) AS TRL_INSP , SUM(MDLRT_SPRT) AS MDLRT_SPRT , SUM(MEDICI_SPRT) AS MEDICI_SPRT , SUM(CLTH_SPRT) AS CLTH_SPRT , SUM(SNITAT_SPRT) AS SNITAT_SPRT , SUM(FDSTFA_SPRT) AS FDSTFA_SPRT , SUM(MVMN_SPRT) AS MVMN_SPRT , SUM(REST_SPRT) AS REST_SPRT , SUM(LVING_SUPLI_SPRT) AS LVING_SUPLI_SPRT , SUM(INFO_PVSN) AS INFO_PVSN , SUM(SRVC_SPRT_CNT_ETC) AS SRVC_SPRT_CNT_ETC , SUM(ACTN_NOPE_MALE) AS ACTN_NOPE_MALE , SUM(ACTN_NOPE_FEMALE) AS ACTN_NOPE_FEMALE , SUM(HMCM) AS HMCM , SUM(SHELTR) AS SHELTR , SUM(OTSHTR) AS OTSHTR , SUM(EMRG_RESC) AS EMRG_RESC , SUM(OTFCLT) AS OTFCLT , SUM(OTHNST) AS OTHNST , SUM(ACTN_MATTER_ETC) AS ACTN_MATTER_ETC FROM TMP GROUP BY FCLTY_TYPE_SE_CD UNION ALL SELECT '00' , COUNT(CASE WHEN UNEART_ACTVT_MTHD_SE_CD = '1' THEN 1 END) AS OFFLINE_NOPE , COUNT(CASE WHEN UNEART_ACTVT_MTHD_SE_CD = '2' THEN 1 END) AS ONLINE_NOPE , COUNT(CASE WHEN UNEART_ACTVT_CL_SE_CD = '1' THEN 1 END) AS DSTNC_DSCSN_CNT , SUM(CASE WHEN UNEART_ACTVT_CL_SE_CD = '1' THEN UNEART_ACTVT_PIC_CNT END) AS DSTNC_DSCSN_NOPE , COUNT(CASE WHEN UNEART_ACTVT_CL_SE_CD = '2' THEN 1 END) AS SHELTR_ONSLF_ACTVT_CNT , SUM(CASE WHEN UNEART_ACTVT_CL_SE_CD = '2' THEN UNEART_ACTVT_PIC_CNT END) AS SHELTR_ONSLF_ACTVT_NOPE , SUM(ERYY_DSCSN_MALE_NOPE) AS ERYY_DSCSN_MALE_NOPE , SUM(ERYY_DSCSN_FEMALE_NOPE) AS ERYY_DSCSN_FEMALE_NOPE , SUM(LVM_YNGBGS_DSCSN) AS LVM_YNGBGS_DSCSN , SUM(DSCSN_ETC) AS DSCSN_ETC , SUM(TRL_INSP) AS TRL_INSP , SUM(MDLRT_SPRT) AS MDLRT_SPRT , SUM(MEDICI_SPRT) AS MEDICI_SPRT , SUM(CLTH_SPRT) AS CLTH_SPRT , SUM(SNITAT_SPRT) AS SNITAT_SPRT , SUM(FDSTFA_SPRT) AS FDSTFA_SPRT , SUM(MVMN_SPRT) AS MVMN_SPRT , SUM(REST_SPRT) AS REST_SPRT , SUM(LVING_SUPLI_SPRT) AS LVING_SUPLI_SPRT , SUM(INFO_PVSN) AS INFO_PVSN , SUM(SRVC_SPRT_CNT_ETC) AS SRVC_SPRT_CNT_ETC , SUM(ACTN_NOPE_MALE) AS ACTN_NOPE_MALE , SUM(ACTN_NOPE_FEMALE) AS ACTN_NOPE_FEMALE , SUM(HMCM) AS HMCM , SUM(SHELTR) AS SHELTR , SUM(OTSHTR) AS OTSHTR , SUM(EMRG_RESC) AS EMRG_RESC , SUM(OTFCLT) AS OTFCLT , SUM(OTHNST) AS OTHNST , SUM(ACTN_MATTER_ETC) AS ACTN_MATTER_ETC FROM TMP ) B ON T_CD = FCLTY_TYPE_SE_CD
ORDER BY T_SN

/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectTlphonDscsnMngStatsList[1388전화상담통계(상담복지센터)] */ /* Lee SangHoon */
WITH TMP AS ( SELECT A.* FROM ACA140 A LEFT JOIN SAA000 F3 ON F3.INST_NO = A.INST_NO
WHERE 1=1 -- 기간구분 AND A.DSCSN_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
)
SELECT T_NM AS SRVC_RESRCE_LCLAS_NM , T_NM2 AS SRVC_RESRCE_MLSFC_NM , T_NM3 AS SRVC_RESRCE_SCLAS_NM , NVL(TRGT_REG_REAL_CONSTT_SE_ME,0) AS TRGT_REG_REAL_CONSTT_SE_ME , NVL(TRGT_REG_REAL_CONSTT_SE_PARNTS,0) AS TRGT_REG_REAL_CONSTT_SE_PARNTS , NVL(TRGT_REG_REAL_CONSTT_SE_FAM,0) AS TRGT_REG_REAL_CONSTT_SE_FAM , NVL(TRGT_REG_REAL_CONSTT_SE_LEADER,0) AS TRGT_REG_REAL_CONSTT_SE_LEADER , NVL(TRGT_REG_REAL_CONSTT_SE_PEPL,0) AS TRGT_REG_REAL_CONSTT_SE_PEPL , NVL(TRGT_REG_REAL_CONSTT_SE_BZMN,0) AS TRGT_REG_REAL_CONSTT_SE_BZMN , NVL(TRGT_REG_REAL_CONSTT_SE_ETC,0) AS TRGT_REG_REAL_CONSTT_SE_ETC , NVL(TRGT_REG_PRCS_HISTB_INFO_PVSN,0) AS TRGT_REG_PRCS_HISTB_INFO_PVSN , NVL(TRGT_REG_PRCS_HISTB_INST_LINK,0) AS TRGT_REG_PRCS_HISTB_INST_LINK FROM ( SELECT A.CMMNS_CD_VALUE AS T_CD , A2.CMMNS_CD_VALUE AS T_CD2 , A3.CMMNS_CD_VALUE AS T_CD3 , A.CMMNS_CD_VALUE_NM AS T_NM , A2.CMMNS_CD_VALUE_NM AS T_NM2 , A3.CMMNS_CD_VALUE_NM AS T_NM3 , A.SRTNG_SQNCE AS T_SN , A2.SRTNG_SQNCE AS T_SN2 , A3.SRTNG_SQNCE AS T_SN3 FROM SAC100 A LEFT JOIN SAC100 A2 ON A2.CMMNS_CD_ID = 'SRVC_RESRCE_MLSFC_SE_CD' AND A2.UP_CMMNS_CD_VALUE = A.CMMNS_CD_VALUE AND A2.USE_YN = 'Y' LEFT JOIN SAC100 A3 ON A3.CMMNS_CD_ID = 'SRVC_RESRCE_SCLAS_SE_CD' AND A3.UP_CMMNS_CD_VALUE = A2.CMMNS_CD_VALUE AND A3.USE_YN = 'Y' WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND A.USE_YN = 'Y' UNION ALL SELECT A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE || '00' , NULL , A.CMMNS_CD_VALUE_NM , '소계' , NULL , A.SRTNG_SQNCE , 0 , NULL FROM SAC100 A WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND A.USE_YN = 'Y' UNION ALL SELECT '00' , '00' , NULL , '합계' , NULL , NULL , 0 , NULL , NULL FROM DUAL ) A LEFT JOIN ( SELECT SRVC_RESRCE_LCLAS_SE_CD , SRVC_RESRCE_MLSFC_SE_CD , SRVC_RESRCE_SCLAS_SE_CD , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '01' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_ME , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '02' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_PARNTS , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '03' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_FAM , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '04' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_LEADER , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '05' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_PEPL , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '06' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_BZMN , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '99' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_ETC , COUNT(CASE WHEN LINK_PRCS_SE_CN = '01' THEN 1 END) AS TRGT_REG_PRCS_HISTB_INFO_PVSN , COUNT(CASE WHEN LINK_PRCS_SE_CN = '02' THEN 1 END) AS TRGT_REG_PRCS_HISTB_INST_LINK FROM TMP GROUP BY SRVC_RESRCE_LCLAS_SE_CD, SRVC_RESRCE_MLSFC_SE_CD, SRVC_RESRCE_SCLAS_SE_CD UNION ALL SELECT SRVC_RESRCE_LCLAS_SE_CD , SRVC_RESRCE_LCLAS_SE_CD || '00' , NULL , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '01' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_ME , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '02' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_PARNTS , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '03' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_FAM , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '04' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_LEADER , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '05' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_PEPL , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '06' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_BZMN , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '99' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_ETC , COUNT(CASE WHEN LINK_PRCS_SE_CN = '01' THEN 1 END) AS TRGT_REG_PRCS_HISTB_INFO_PVSN , COUNT(CASE WHEN LINK_PRCS_SE_CN = '02' THEN 1 END) AS TRGT_REG_PRCS_HISTB_INST_LINK FROM TMP GROUP BY SRVC_RESRCE_LCLAS_SE_CD UNION ALL SELECT '00' , '00' , NULL , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '01' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_ME , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '02' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_PARNTS , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '03' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_FAM , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '04' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_LEADER , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '05' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_PEPL , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '06' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_BZMN , COUNT(CASE WHEN REAL_CONSTT_SE_CD = '99' THEN 1 END) AS TRGT_REG_REAL_CONSTT_SE_ETC , COUNT(CASE WHEN LINK_PRCS_SE_CN = '01' THEN 1 END) AS TRGT_REG_PRCS_HISTB_INFO_PVSN , COUNT(CASE WHEN LINK_PRCS_SE_CN = '02' THEN 1 END) AS TRGT_REG_PRCS_HISTB_INST_LINK FROM TMP ) B ON T_CD = SRVC_RESRCE_LCLAS_SE_CD AND T_CD2 = SRVC_RESRCE_MLSFC_SE_CD AND T_CD3 = SRVC_RESRCE_SCLAS_SE_CD
ORDER BY T_SN, T_SN2, T_SN3

/* isry.itgcm.unitystats.mapper.UnitystatsMapper - selectEmrgIntrvnMngStatsList[긴급구조통계(지자체안정망,상담복지센터)] */ /* Lee SangHoon */
WITH TMP AS ( SELECT A.PROBM_STTS_LCLAS_SE_CD , A.PROBM_STTS_MLSFC_SE_CD , A.PROBM_STTS_SCLAS_SE_CD , B.EMRG_INTRVN_ACTN_SE_CD , B.EMRG_INTRVN_OUTSD_LINK_SE_CD FROM SEA220 A LEFT JOIN SEA270 B ON B.EMRG_INTRVN_NO = A.EMRG_INTRVN_NO LEFT JOIN SAA000 F3 ON F3.INST_NO = A.CONSTT_INST_NO
WHERE 1=1 -- 단위업무구분 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.RCPT_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
-- 시도코드 AND F3.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F3.SGG_CD = #{SGG_CD}
-- 기관번호 AND F3.INST_NO = #{INST_NO}
)
SELECT T_NM AS PROBM_STTS_LCLAS_NM , T_NM2 AS PROBM_STTS_MLSFC_NM , T_NM3 AS PROBM_STTS_SCLAS_NM , NVL(TOT,0) AS ALL_NOPE , NVL(DRCT_INTRVN,0) AS DRCT_INTRVN , NVL(FAM,0) AS FAM , NVL(EMRG_RESC,0) AS EMRG_RESC , NVL(YNGBGS_SHELTR,0) AS YNGBGS_SHELTR , NVL(SCHL,0) AS SCHL , NVL(INST_LINK_ETC,0) AS INST_LINK_ETC , NVL(UTZTN_PSBLTY_INST_INFO,0) AS UTZTN_PSBLTY_INST_INFO , NVL(DCLR_MTHD_GUIDAN,0) AS DCLR_MTHD_GUIDAN , NVL(INFO_PVSN_ETC,0) AS INFO_PVSN_ETC , NVL(ACTN_NO_PSBLTY,0) AS ACTN_NO_PSBLTY FROM ( -- 통계 틀 만들기 SELECT A.CMMNS_CD_VALUE AS T_CD , A2.CMMNS_CD_VALUE AS T_CD2 , A3.CMMNS_CD_VALUE AS T_CD3 , A.CMMNS_CD_VALUE_NM AS T_NM , A2.CMMNS_CD_VALUE_NM AS T_NM2 , A3.CMMNS_CD_VALUE_NM AS T_NM3 , A.SRTNG_SQNCE AS T_SN , A2.SRTNG_SQNCE AS T_SN2 , A3.SRTNG_SQNCE AS T_SN3 FROM SAC100 A LEFT JOIN SAC100 A2 ON A2.CMMNS_CD_ID = 'PROBM_STTS_MLSFC_SE_CD' AND A2.UP_CMMNS_CD_VALUE = A.CMMNS_CD_VALUE AND A2.USE_YN = 'Y' LEFT JOIN SAC100 A3 ON A3.CMMNS_CD_ID = 'PROBM_STTS_SCLAS_SE_CD' AND A3.UP_CMMNS_CD_VALUE = A2.CMMNS_CD_VALUE AND A3.USE_YN = 'Y' WHERE A.CMMNS_CD_ID = 'PROBM_STTS_LCLAS_SE_CD' AND A.USE_YN = 'Y' UNION ALL SELECT A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE || '00' , NULL , A.CMMNS_CD_VALUE_NM , '소계' , NULL , A.SRTNG_SQNCE , 0 , NULL FROM SAC100 A WHERE A.CMMNS_CD_ID = 'PROBM_STTS_LCLAS_SE_CD' UNION ALL SELECT '00' , '00' , NULL , '합계' , NULL , NULL , 0 , NULL , NULL FROM DUAL ) A LEFT JOIN ( SELECT PROBM_STTS_LCLAS_SE_CD , PROBM_STTS_MLSFC_SE_CD , PROBM_STTS_SCLAS_SE_CD , COUNT(*) AS TOT , COUNT(CASE EMRG_INTRVN_ACTN_SE_CD WHEN '01' THEN 1 END) AS DRCT_INTRVN , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '01' THEN 1 END) AS FAM , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '02' THEN 1 END) AS EMRG_RESC , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '03' THEN 1 END) AS YNGBGS_SHELTR , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '04' THEN 1 END) AS SCHL , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '09' THEN 1 END) AS INST_LINK_ETC , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '11' THEN 1 END) AS UTZTN_PSBLTY_INST_INFO , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '12' THEN 1 END) AS DCLR_MTHD_GUIDAN , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '99' THEN 1 END) AS INFO_PVSN_ETC , COUNT(CASE EMRG_INTRVN_ACTN_SE_CD WHEN '04' THEN 1 END) AS ACTN_NO_PSBLTY FROM TMP GROUP BY PROBM_STTS_LCLAS_SE_CD, PROBM_STTS_MLSFC_SE_CD, PROBM_STTS_SCLAS_SE_CD UNION ALL SELECT PROBM_STTS_LCLAS_SE_CD , PROBM_STTS_LCLAS_SE_CD || '00' , NULL , COUNT(*) AS TOT , COUNT(CASE EMRG_INTRVN_ACTN_SE_CD WHEN '01' THEN 1 END) AS DRCT_INTRVN , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '01' THEN 1 END) AS FAM , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '02' THEN 1 END) AS EMRG_RESC , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '03' THEN 1 END) AS YNGBGS_SHELTR , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '04' THEN 1 END) AS SCHL , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '09' THEN 1 END) AS INST_LINK_ETC , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '11' THEN 1 END) AS UTZTN_PSBLTY_INST_INFO , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '12' THEN 1 END) AS DCLR_MTHD_GUIDAN , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '99' THEN 1 END) AS INFO_PVSN_ETC , COUNT(CASE EMRG_INTRVN_ACTN_SE_CD WHEN '04' THEN 1 END) AS ACTN_NO_PSBLTY FROM TMP GROUP BY PROBM_STTS_LCLAS_SE_CD UNION ALL SELECT '00' , '00' , NULL , COUNT(*) AS TOT , COUNT(CASE EMRG_INTRVN_ACTN_SE_CD WHEN '01' THEN 1 END) AS DRCT_INTRVN , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '01' THEN 1 END) AS FAM , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '02' THEN 1 END) AS EMRG_RESC , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '03' THEN 1 END) AS YNGBGS_SHELTR , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '04' THEN 1 END) AS SCHL , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '09' THEN 1 END) AS INST_LINK_ETC , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '11' THEN 1 END) AS UTZTN_PSBLTY_INST_INFO , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '12' THEN 1 END) AS DCLR_MTHD_GUIDAN , COUNT(CASE EMRG_INTRVN_OUTSD_LINK_SE_CD WHEN '99' THEN 1 END) AS INFO_PVSN_ETC , COUNT(CASE EMRG_INTRVN_ACTN_SE_CD WHEN '04' THEN 1 END) AS ACTN_NO_PSBLTY FROM TMP ) B ON B.PROBM_STTS_LCLAS_SE_CD = A.T_CD AND B.PROBM_STTS_MLSFC_SE_CD = A.T_CD2 AND (B.PROBM_STTS_SCLAS_SE_CD = A.T_CD3 OR B.PROBM_STTS_SCLAS_SE_CD IS NULL)
ORDER BY T_SN, T_SN2, T_SN3
